//! 🔊️ Controlled native channel/sample/tag construction preserves every Binary32 word.
use semio_framework_value::{ValueError,ValueRefusalKind};
use super::{SemioAudioSnapshot,SemioAudioChannel,SemioAudioTag,SemioAudioFormat,STDIO_SEMIOAUDIO_DOCUMENT_SCHEMA};
use crate::standards::v1::subsets::base::schema::snapshot::native_decoding as native;
use semio_framework_value::native_decoding::NativeDecodeControl;
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits};
pub(super) fn decode(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<SemioAudioSnapshot,ValueError>{native::decode(payload,STDIO_SEMIOAUDIO_DOCUMENT_SCHEMA,control,binary,document)}
pub(crate) fn binary(body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioAudioSnapshot,ValueError>{
 let mut entities=0;native::entities(&mut entities,1,limits)?;let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unsupported Semio audio native format"))}
 let schema=native::text(&mut reader,control)?;let sample_rate=reader.read_u32_le().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?;let format=super::format_from_tag(reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?).map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error))?;let count=native::length(&mut reader)?;native::entities(&mut entities,count,limits)?;let mut channels=control.allocate_vec::<SemioAudioChannel>(count)?;
 control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{let count=native::length(&mut reader)?;native::entities(&mut entities,count,limits)?;let mut samples=control.allocate_vec::<f32>(count)?;control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{samples.push(f32::from_bits(reader.read_u32_le().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?));control.step()?;}Ok::<_,ValueError>(())})?;channels.push(SemioAudioChannel{samples});control.step()?;}Ok::<_,ValueError>(())})?;
 let count=native::length(&mut reader)?;native::entities(&mut entities,count,limits)?;let mut tags=control.allocate_vec::<SemioAudioTag>(count)?;control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{let key=native::text(&mut reader,control)?;let value=native::text(&mut reader,control)?;tags.push(SemioAudioTag{key,value});control.step()?;}Ok::<_,ValueError>(())})?;
 if reader.remaining()!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Semio audio native trailing bytes"))}Ok(SemioAudioSnapshot{schema,sample_rate,format,channels,tags})
}
pub(crate) fn document(body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioAudioSnapshot,ValueError>{
 let mut entities=0;native::entities(&mut entities,1,limits)?;let fields=native::fields(body,["schema","sampleRate","format","channels","tags"],control)?;let schema=native::hex_text(fields[0].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Semio audio native schema field missing"))?,control)?;let sample_rate=super::parse_u32(fields[1].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Semio audio native sample rate missing"))?).map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error))?;let format=match fields[2]{Some("pcm8")=>SemioAudioFormat::Pcm8,Some("pcm16")|None=>SemioAudioFormat::Pcm16,Some("pcm24")=>SemioAudioFormat::Pcm24,Some("pcm32")=>SemioAudioFormat::Pcm32,Some("f32")=>SemioAudioFormat::Float32,Some("f64")=>SemioAudioFormat::Float64,Some(_)=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio audio native format"))};
 let mut items=native::Items::new(fields[3].unwrap_or("[]"))?;let count=items.count(control,limits.max_rows)?;native::entities(&mut entities,count,limits)?;let mut channels=control.allocate_vec::<SemioAudioChannel>(count)?;
 control.scoped_stage(|control|{control.begin_stage(count)?;while let Some(value)=items.next(control)?{let mut sample_items=native::Items::new(value)?;let count=sample_items.count(control,limits.max_rows)?;native::entities(&mut entities,count,limits)?;let mut samples=control.allocate_vec::<f32>(count)?;control.scoped_stage(|control|{control.begin_stage(count)?;while let Some(value)=sample_items.next(control)?{let word=u32::from_str_radix(value,16).map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?;samples.push(f32::from_bits(word));control.step()?;}Ok::<_,ValueError>(())})?;channels.push(SemioAudioChannel{samples});control.step()?;}Ok::<_,ValueError>(())})?;
 let mut items=native::Items::new(fields[4].unwrap_or("[]"))?;let count=items.count(control,limits.max_rows)?;native::entities(&mut entities,count,limits)?;let mut tags=control.allocate_vec::<SemioAudioTag>(count)?;control.scoped_stage(|control|{control.begin_stage(count)?;while let Some(value)=items.next(control)?{let[key,value]=native::record(value,control)?;let key=native::hex_text(key,control)?;let value=native::hex_text(value,control)?;tags.push(SemioAudioTag{key,value});control.step()?;}Ok::<_,ValueError>(())})?;
 Ok(SemioAudioSnapshot{schema,sample_rate,format,channels,tags})
}
